// Render a captured conversation jsonl into a compact, timestamped transcript digest.
import { readFileSync } from 'node:fs';

const file = process.argv[2];
const maxText = Number(process.argv[3] || 1200);
const lines = readFileSync(file, 'utf8').split('\n').filter(Boolean);

const clip = (s, n = maxText) => {
  s = String(s ?? '').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + ` …[+${s.length - n}ch]` : s;
};

let first = null, last = null;
for (const line of lines) {
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  const ts = e.timestamp || '';
  if (ts) { if (!first) first = ts; last = ts; }
  const t = ts ? ts.slice(11, 19) : '--:--:--';
  const m = e.message;
  const side = e.isSidechain ? 'SUB ' : '';
  if (e.type === 'user') {
    const c = m?.content;
    if (typeof c === 'string') {
      console.log(`\n[${t}] ${side}USER: ${clip(c, 2500)}`);
    } else if (Array.isArray(c)) {
      for (const b of c) {
        if (b.type === 'text') console.log(`\n[${t}] ${side}USER: ${clip(b.text, 2500)}`);
        else if (b.type === 'tool_result') {
          const body = typeof b.content === 'string' ? b.content
            : Array.isArray(b.content) ? b.content.map(x => x.text || `<${x.type}>`).join(' ') : '';
          console.log(`[${t}] ${side}  <- ${b.is_error ? 'ERROR ' : ''}${clip(body, b.is_error ? 700 : 260)}`);
        }
      }
    }
  } else if (e.type === 'assistant') {
    const usage = m?.usage ? ` {in:${(m.usage.input_tokens||0)+(m.usage.cache_read_input_tokens||0)} out:${m.usage.output_tokens||0}}` : '';
    for (const b of m?.content || []) {
      if (b.type === 'text' && b.text.trim()) console.log(`[${t}] ${side}ASST${usage}: ${clip(b.text)}`);
      else if (b.type === 'thinking' && process.env.SHOW_THINK) console.log(`[${t}] ${side}THINK: ${clip(b.thinking, 800)}`);
      else if (b.type === 'tool_use') {
        const inp = JSON.stringify(b.input);
        console.log(`[${t}] ${side}  -> ${b.name}(${clip(inp, 420)})`);
      }
    }
  } else if (e.type === 'system') {
    if (e.subtype && e.subtype !== 'post_tool_use_hook') console.log(`[${t}] SYS(${e.subtype}): ${clip(e.content || '', 200)}`);
  }
}
console.error(`# ${file}\n# entries=${lines.length} first=${first} last=${last}`);

